const C=window.SITE_CONFIG;let newsSearch='',helpFilter='全部',helpSearch='',timer;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={money:'M8 3h8l-2 4h-4zM10 7c-4 3-6 6-6 10 0 5 16 5 16 0 0-4-2-7-6-10M9 12l3 3 3-3M9 16h6m-3-1v5',document:'M6 3h9l4 4v14H6zM14 3v6h5M9 12h7m-7 4h4',court:'M3 9l9-6 9 6H3zM5 11v8m5-8v8m4-8v8m5-8v8M3 21h18',gavel:'m8 3 7 7-3 3-7-7zM14 9l3-3 4 4-3 3M10 12 4 18m-1 3h18M8 19h10',unlock:'M8 10V7a4 4 0 0 1 8 0M5 10h14v11H5zM12 14v3',building:'M4 21V7l8-4 8 4v14M2 21h20M8 8v2m4-3v3m4-2v2M8 13v2m4-2v2m4-2v2M10 21v-3h4v3',chip:'M7 7h10v10H7zM10 10h4v4h-4zM9 3v4m6-4v4M9 17v4m6-4v4M3 9h4m-4 6h4m10-6h4m-4 6h4',leaf:'M20 3c-9 0-15 3-15 9a7 7 0 0012 5c3-3 3-8 3-14zM3 21L15 9',link:'M10 14l4-4M8 16l-2 2a4 4 0 01-6-6l5-5a4 4 0 016 0M16 8l2-2a4 4 0 016 6l-5 5a4 4 0 01-6 0',arrow:'M4 12h15m-6-6 6 6-6 6',search:'M21 21l-5-5M18 10a8 8 0 11-16 0 8 8 0 0116 0',phone:'M5 3h4l2 5-3 2a16 16 0 006 6l2-3 5 2v4c-1 5-18-2-18-13z',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1114 0zM14 10a2 2 0 11-4 0 2 2 0 014 0',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',users:'M16 21v-3a4 4 0 00-4-4H7a4 4 0 00-4 4v3M14 4a4 4 0 010 8m7 9v-3a4 4 0 00-3-4M13 7a4 4 0 11-8 0 4 4 0 018 0',clock:'M12 7v5l3 2M22 12a10 10 0 11-20 0 10 10 0 0120 0'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.building}"/></svg>`;
const link=(url,label,cls='')=>`<a class="${cls}" href="#${url}">${label}</a>`;
function applyTheme(t){const theme=C.themes[t]||C.themes[C.theme];for(const [k,v] of Object.entries(theme))if(k!=='name')document.documentElement.style.setProperty('--'+k,v);try{localStorage.setItem('region-theme',t)}catch{}document.querySelectorAll('[data-theme]').forEach(b=>{b.classList.toggle('active',b.dataset.theme===t);b.setAttribute('aria-pressed',b.dataset.theme===t)})}
const nav=[['/','首页'],['/scenarios','保函介绍'],['/institutions','合作机构'],['/news','最新资讯'],['/help','帮助中心'],['/about','关于我们']];
function header(route){return `<a class="skip-link" href="#main">跳至主要内容</a><header class="site-header"><div class="container nav-wrap"><a class="brand" href="#/" aria-label="${esc(C.brand)}首页"><span class="brandmark"><b></b><b></b><b></b></span><span class="brand-name">${esc(C.brand)}</span><span class="brand-sub">${esc(C.subtitle)}</span></a><button class="mobile-menu" aria-label="展开导航" aria-expanded="false"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button><nav aria-label="主导航">${nav.map(([p,l])=>link(p,l,(p==='/'?route==='/':route.startsWith(p))?'active':'')).join('')}</nav><button class="header-start" data-focus-chat>问保函问题 ${icon('arrow')}</button></div></header>`}

function themeControls(){return `<div class="theme-switch" aria-label="网站主题"><span>主题</span>${Object.entries(C.themes).map(([k,v])=>`<button data-theme="${k}" style="--swatch:${v.primary}" title="${v.name}" aria-label="切换${v.name}" aria-pressed="false"></button>`).join('')}</div>`}
function footer(){const f=C.footer,c=C.contact;return `<footer class="corporate-footer"><div class="footer-lines" aria-hidden="true"></div><div class="container corporate-footer-main"><section class="footer-introduction" aria-label="平台介绍"><a class="brand footer-brand" href="#/"><span class="brandmark"><b></b><b></b><b></b></span><span class="brand-name">${esc(C.brand)}</span></a><p>${esc(f.description)}</p></section><section class="footer-contact"><h2>联系我们</h2>${c.phone?`<a class="footer-hotline" href="tel:${esc(c.phone)}">${esc(c.phone)}</a>`:'<p class="footer-contact-heading">服务咨询</p>'}<dl><div><dt>联系手机：</dt><dd>${c.mobile?`<a href="tel:${esc(c.mobile)}">${esc(c.mobile)}</a>`:'暂未公布'}</dd></div><div><dt>邮箱：</dt><dd>${c.email?`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`:'暂未公布'}</dd></div><div><dt>地址：</dt><dd>${c.address?esc(c.address):'暂未公布'}</dd></div></dl></section><nav class="footer-navigation" aria-label="页脚快捷导航"><h2>快捷导航</h2>${nav.filter(([p])=>['/scenarios','/institutions','/news','/about'].includes(p)).map(([p,l])=>link(p,l)).join('')}</nav><section class="footer-mobile"><h2>小程序入口</h2>${c.qrImage?`<img class="footer-miniprogram-qr" src="${esc(c.qrImage)}" alt="微信小程序二维码" width="96" height="96" loading="lazy">`:'<div class="footer-qr-space" aria-label="微信小程序暂未开放"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4M10 5h4"/></svg><span>暂未开放</span></div>'}<p>${esc(c.qrLabel)}</p></section></div><div class="container corporate-footer-legal"><p class="footer-company">© ${new Date().getFullYear()} ${esc(f.company||c.copyright)}</p><p class="footer-disclaimer">${esc(f.disclaimer)}</p>${c.filing||f.publicSecurityFiling?`<div class="footer-filings">${c.filing?`<a href="https://beian.miit.gov.cn/" target="_blank" rel="noopener noreferrer">${esc(c.filing)}</a>`:''}${f.publicSecurityFiling?`<span>${esc(f.publicSecurityFiling)}</span>`:''}</div>`:''}<div class="footer-tools">${themeControls()}</div></div></footer>`}

function city(){let buildings='';const specs=[[95,163,53,110],[164,108,65,161],[249,142,60,124],[322,67,66,192],[406,121,54,140],[473,164,47,104]];specs.forEach(([x,y,w,h],i)=>{buildings+=`<path d="M${x} ${y}l${w} -24v${h}l-${w} 27z" fill="url(#glass)"/><path d="M${x+w} ${y-24}l28 19v${h}l-28 -19z" fill="#a9ccf6"/><path d="M${x} ${y}l${w} -24 28 19-${w} 26z" fill="#edf7ff"/>`;for(let row=1;row<h/18;row++)buildings+=`<path d="M${x+7} ${y+row*16}l${w-14} -19" stroke="#b4d3f5" stroke-width="3"/>`});return `<svg viewBox="0 0 640 430" class="city-art" aria-label="连接城市产业与金融的数字城市插画" role="img"><defs><linearGradient id="glass" x2="0" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#c1dbfa"/></linearGradient><linearGradient id="land"><stop stop-color="#c5ddfa"/><stop offset="1" stop-color="#f5faff"/></linearGradient></defs><ellipse cx="325" cy="350" rx="280" ry="65" fill="#d4e6ff" opacity=".5"/><path d="M45 295L325 155l275 141-275 140z" fill="#b0cff6"/><path d="M45 283L325 143l275 141-275 140z" fill="url(#land)"/><g opacity=".65" stroke="white" stroke-width="5"><path d="M100 310l280-140M165 345l280-140M230 380l280-140M110 250l280 142M180 215l280 142M250 180l280 142"/></g>${buildings}<path d="M60 274Q230 88 531 169" fill="none" stroke="#6d9fee" stroke-width="2" stroke-dasharray="7 7"/><path d="M83 304Q344 421 565 214" fill="none" stroke="#5594ec" stroke-width="2"/><g fill="#4b91e9"><circle cx="83" cy="304" r="5"/><circle cx="565" cy="214" r="5"/></g><g transform="translate(340 18)"><circle r="32" fill="#fff"/><circle r="25" fill="#eaf3ff"/><path d="M-10-10L0 0 10-10M0 0v17M-10 4h20M-10 10h20" stroke="#4282e1" fill="none" stroke-width="3"/></g><g transform="translate(116 116)"><rect x="-24" y="-24" width="48" height="48" rx="13" fill="white"/><path d="M-12 12V-5L0-12 12-5v17M-6 12V3H6v9" fill="none" stroke="#6595df" stroke-width="2"/></g><g transform="translate(540 118)"><rect x="-24" y="-24" width="48" height="48" rx="13" fill="white"/><path d="M0-13l12 5v8c0 9-12 14-12 14S-12 9-12 0v-8zM-6 0l4 4 8-8" stroke="#5388df" fill="none" stroke-width="2"/></g></svg>`}
function sectionHead(eyebrow,title,desc,to,label){return `<div class="section-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${to?link(to,label+' '+icon('arrow'),'text-link'):''}</div>`}
function scenarioCards(){return C.scenarios.map((s,i)=>link('/scenarios/'+s.id,`<div class="scenario-visual"><img src="${esc(s.image)}" alt="${esc(s.imageAlt)}" width="960" height="600" loading="${i<2?'eager':'lazy'}" decoding="async"><span class="scene-frame" aria-hidden="true"></span><span class="scene-number" aria-hidden="true">SCENE / 0${i+1}</span><span class="scene-caption">${esc(s.imageCaption)}</span><span class="scene-view" aria-hidden="true">了解场景 ${icon('arrow')}</span></div><div class="scenario-copy"><div class="scene-heading"><span class="scene-ordinal">0${i+1}</span><div><span class="card-kicker">${esc(s.label)}</span><h3>${esc(s.title)}</h3></div><span class="scene-heading-icon">${icon(s.icon)}</span></div><p>${esc(s.desc)}</p><div class="card-bottom"><span>${s.tags.map(x=>'<span>'+esc(x)+'</span>').join('')}</span><span class="scene-read">查看所需材料 ${icon('arrow')}</span></div></div>`,'scenario-card scenario-photo-card editorial-scene')).join('')}
function bankCards(){
  return C.institutions.map(b => `<div class="bank-card institution-logo-card">
    <span class="institution-status ${b.status==='已上线'?'joined':'connecting'}"><i></i>${esc(b.status)}</span>
    <strong>${esc(b.name)}</strong></div>`).join('');
}

function selectHomeSlide(name){
  document.querySelectorAll('[data-home-panel]').forEach(panel => {
    panel.hidden = panel.dataset.homePanel !== name;
  });
  document.querySelectorAll('[data-slide]').forEach(button => {
    button.setAttribute('aria-pressed', String(button.dataset.slide === name));
  });
}
function home(){const h=C.home;return `<section class="intelligence-hero home-carousel" aria-label="首页推荐">
  <div class="hero-gridlines" aria-hidden="true"></div><div class="hero-glow" aria-hidden="true"></div>
  <div class="home-slide-controls" role="group" aria-label="切换首屏内容">
    <button type="button" data-slide="launch" aria-controls="launch-panel" aria-pressed="true">功能上新</button>
    <button type="button" data-slide="chat" aria-controls="chat-panel" aria-pressed="false">保函问答</button>
  </div>
  <div class="container launch-panel" id="launch-panel" data-home-panel="launch">
    <h1>案件编排工具<span>使用新功能上线</span></h1>
    <img class="launch-photo" src="assets/scenarios/evidence.jpg" alt="" width="960" height="600" fetchpriority="high">
  </div>
  <div id="chat-panel" data-home-panel="chat" hidden><div class="container intelligence-content"><div class="hero-caption"><span class="caption-dot"></span>${esc(C.subtitle)}<span class="caption-divider"></span><span>SERVICE, SIMPLIFIED.</span></div><h1>${esc(h.title)}<br><span>${esc(h.titleAccent)}</span></h1><p class="intelligence-description">${esc(h.description)}</p><div class="assistant-shell">${window.SiteAssistant.html()}</div><div class="hero-footnotes"><span>${icon('shield')}查材料，无需注册</span><span>${icon('book')}当事人、律师都能查</span><span>${icon('link')}办理入口筹备中</span></div></div></div>
</section><section class="container discovery-section"><div class="discovery-heading"><div><h2>你遇到的，<span>是哪种情况？</span></h2></div><p>想保全对方财产，还是自己的账户被冻结？<br>选一个符合你的情况，先看要准备什么。</p></div><div class="discovery-grid">${h.paths.map((item,i)=>`<button class="discovery-card" data-ask="${esc(item.question)}"><div class="discovery-card-top"><span class="discovery-icon">${icon(item.icon)}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><div class="discovery-card-action">${esc(item.action)} ${icon('arrow')}</div></button>`).join('')}</div></section>`}

function pageHero(en,title,desc){return `<section class="page-hero"><div class="container"><div class="eyebrow">${en}</div><h1>${title}</h1><p>${desc}</p></div></section>`}
const tabs=(items,current,attr)=>`<div class="tabs" role="group" aria-label="按分类筛选">${items.map(x=>`<button ${attr}="${esc(x)}" class="${current===x?'active':''}" aria-pressed="${current===x}">${esc(x)}</button>`).join('')}</div>`;
function scenarios(){return window.JourneyUI.html()}
function scenarioDetail(id){const s=C.scenarios.find(x=>x.id===id);return s?window.JourneyUI.detail(s):missing()}
function admission(){
  const sections = C.admission.map(({title, paragraphs}) => `<section>
    <h2><strong>${esc(title)}</strong></h2>
    ${paragraphs.map(paragraph => `<p>${esc(paragraph)}</p>`).join('')}
  </section>`).join('');
  return `<section class="container section"><div class="breadcrumb">${link('/institutions','合作机构')} / 准入说明</div>
    <article class="article reading"><h1>准入说明</h1>${sections}
    <div class="article-end">${link('/institutions','← 返回合作机构')}<button class="button primary" data-join>申请准入</button></div>
    </article></section>`;
}
function institutions(){
  return pageHero('SERVICE PARTNERS','合作机构','查看合作金融机构及其对接进度。')+`
    <section class="container section">
      ${sectionHead('','合作金融机构','')}
      <div class="bank-grid institutions-grid">${bankCards()}</div>
      <div class="join-block"><div><h2>金融机构入驻</h2><button class="button primary" data-join>申请准入 ${icon('arrow')}</button></div>
      <div><h3>准入说明</h3><p>公开征集，符合要求的保险机构均可接入。</p>
      ${link('/institutions/admission','查看完整准入说明 '+icon('arrow'),'text-link')}</div></div>
    </section>`;
}
function news(){const filtered=C.news.filter(n=>(n.title+n.summary).includes(newsSearch));return pageHero('NEWS & INSIGHTS','最新资讯','办保函前要问什么、准备什么，在这里逐项查看。')+`<section class="container section"><div class="list-toolbar news-toolbar"><p class="results-count">共 ${filtered.length} 篇资讯${newsSearch?' · 搜索「'+esc(newsSearch)+'」':''}</p><form id="news-search" class="search-box"><input aria-label="搜索资讯" placeholder="搜索资讯关键词" value="${esc(newsSearch)}"><button aria-label="搜索">${icon('search')}</button></form></div><div class="article-list">${filtered.length?filtered.map(n=>link('/news/'+n.id,`${n.image?`<img class="news-thumbnail" src="${esc(n.image)}" alt="${esc(n.imageAlt||n.title)}" loading="lazy">`:''}<div class="news-list-copy"><h2>${esc(n.title)}</h2><p>${esc(n.summary)}</p><time class="news-list-date" datetime="${esc(n.date)}">${esc(n.date)}</time></div>${icon('arrow')}`,'article-list-row'+(n.image?' has-image':' no-image'))).join(''):'<div class="empty">未找到相关资讯，请尝试其他关键词。<button data-clear-news>清除搜索</button></div>'}</div><div class="pagination"><span>共 ${filtered.length} 条</span><button aria-current="page">1</button></div></section>`}

function newsDetail(id){const n=C.news.find(x=>x.id===id);if(!n)return missing();return `<section class="container section"><div class="breadcrumb">${link('/','首页')} / ${link('/news','最新资讯')} / 资讯详情</div><article class="article reading"><span class="tag">${esc(n.category)}</span><h1>${esc(n.title)}</h1><div class="article-meta">发布时间：${n.date}　|　来源：${esc(C.brand)}</div>${n.body.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="article-end">${link('/news','← 返回资讯列表')}<button onclick="window.print()">打印文章</button></div></article></section>`}
function help(){const faqs=C.faqs.filter(f=>(helpFilter==='全部'||helpFilter===f.category)&&(f.q+f.a).includes(helpSearch));return `<section class="help-hero"><div class="container"><div class="eyebrow">HELP CENTER</div><h1>您好，有什么可以帮您？</h1><p>查材料、费用、出函时间，以及保函到期后的处理。</p><form id="help-search" class="search-box large">${icon('search')}<input aria-label="搜索帮助问题" placeholder="请输入关键词，例如：材料、期限、合作" value="${esc(helpSearch)}"><button class="button primary">搜索</button></form><span class="hot-search">热门搜索：<button data-keyword="材料">材料准备</button><button data-keyword="期限">保函期限</button><button data-keyword="合作">机构合作</button></span></div></section><section class="container section help-layout"><aside class="help-categories"><h3>问题分类</h3>${tabs(['全部','平台使用','材料准备','担保知识','机构合作'],helpFilter,'data-help-filter')}</aside><div class="faq-content"><h2>${helpSearch?'搜索结果':'常见问题'} <small>${faqs.length} 个问题</small></h2>${faqs.length?faqs.map(f=>link('/help/'+f.id,`<span>${icon('book')} ${esc(f.q)}</span>${icon('arrow')}`,'faq-row')).join(''):'<div class="empty">暂未找到相关问题。<button data-clear-help>清除筛选</button></div>'}<div class="help-contact"><div><h3>还没有找到答案？</h3><p>查看保函用途，对照具体情况了解准备事项。</p></div>${link('/scenarios','查看保函用途','button outline')}</div></div></section>`}
function helpDetail(id){const f=C.faqs.find(x=>x.id===id);if(!f)return missing();return pageHero('HELP CENTER','问题详情','查看平台使用与诉讼担保的常见问题。')+`<section class="container section"><article class="article reading"><a class="back-link" href="#/help">← 返回帮助中心</a><span class="tag">${esc(f.category)}</span><h1>${esc(f.q)}</h1><p>${esc(f.a)}</p><div class="help-contact"><span>需要进一步帮助？</span>${link('/scenarios','查看保函用途','button outline')}</div></article></section>`}
function about(){
  const paragraphs = C.about.paragraphs.map(text => {
    const body = esc(text).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    return `<p>${body}</p>`;
  }).join('');
  return `<section class="container section about-intro"><article><div class="eyebrow">关于我们</div><h1><strong>${esc(C.about.title)}</strong></h1>${paragraphs}</article><div class="about-art">${city()}</div></section>`;
}
function missing(){return '<section class="container section empty"><h1>页面暂不存在</h1><p>请返回首页选择其他内容。</p><a class="button primary" href="#/">返回首页</a></section>'}
function render(scroll=true){window.SceneMotion?.destroy();clearTimeout(timer);const route=(location.hash.slice(1)||'/').split('?')[0];const bits=route.split('/').filter(Boolean);let html;if(!bits.length)html=home();else if(bits[0]==='scenarios')html=bits[1]?scenarioDetail(bits[1]):scenarios();else if(bits[0]==='institutions')html=bits[1]==='admission'?admission():institutions();else if(bits[0]==='news')html=bits[1]?newsDetail(bits[1]):news();else if(bits[0]==='help')html=bits[1]?helpDetail(bits[1]):help();else if(bits[0]==='about')html=about();else html=missing();$('#app').innerHTML=header(route)+`<main id="main" tabindex="-1">${html}</main>`+footer();let t=C.theme;try{t=localStorage.getItem('region-theme')||C.theme}catch{}applyTheme(t);bind();if(scroll)window.scrollTo(0,0);document.title=(nav.find(([p])=>p==='/'?route==='/':route.startsWith(p))?.[1]||'详情')+' · '+C.brand+' · '+C.subtitle;window.SceneMotion?.init()}
function onAll(s,e,fn){document.querySelectorAll(s).forEach(x=>x.addEventListener(e,fn))}
function bind(){window.JourneyUI.bind();const skip=$('.skip-link');if(skip)skip.onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'})};window.SiteAssistant.bind();onAll('[data-focus-chat]','click',()=>{selectHomeSlide('chat');window.SiteAssistant.focus()});onAll('[data-ask]','click',e=>{selectHomeSlide('chat');window.SiteAssistant.ask(e.currentTarget.dataset.ask)});onAll('[data-theme]','click',e=>applyTheme(e.currentTarget.dataset.theme));onAll('[data-slide]','click',e=>selectHomeSlide(e.currentTarget.dataset.slide));onAll('[data-contact]','click',contactModal);onAll('[data-join]','click',joinModal);for(const [a,set]of [['help-filter',v=>helpFilter=v]])onAll(`[data-${a}]`,'click',e=>{set(e.currentTarget.getAttribute('data-'+a));render(false)});if($('#news-search'))$('#news-search').onsubmit=e=>{e.preventDefault();newsSearch=e.target.querySelector('input').value.trim();render(false)};if($('#help-search'))$('#help-search').onsubmit=e=>{e.preventDefault();helpSearch=e.target.querySelector('input').value.trim();render(false)};onAll('[data-keyword]','click',e=>{helpSearch=e.currentTarget.dataset.keyword;helpFilter='全部';render(false)});onAll('[data-clear-help]','click',()=>{helpSearch='';helpFilter='全部';render(false)});onAll('[data-clear-news]','click',()=>{newsSearch='';render(false)});$('.mobile-menu').onclick=e=>{const open=$('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)}}
let previousFocus;
function openModal(title,body){clearTimeout(timer);previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><h2 id="modal-title">${title}</h2><button data-close aria-label="关闭弹窗">×</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('[data-close]').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal()};$('.modal').focus()}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
function contactInfo(){return [C.contact.phone?`<a class="footer-phone" href="tel:${esc(C.contact.phone)}">${esc(C.contact.phone)}</a>`:'',C.contact.phone?`<p>${esc(C.contact.hours)}</p>`:'',C.contact.address?`<p>${esc(C.contact.address)}</p>`:'',C.contact.email?`<p><a href="mailto:${esc(C.contact.email)}">${esc(C.contact.email)}</a></p>`:''].join('')||'<p>人工咨询渠道暂未开放</p><p>服务相关问题可先查阅帮助中心。</p>'}
function contactModal(){openModal('联系'+C.brand,`<p>办保函前，请先准备法院名称、申请金额和法院的担保要求。</p><div class="contact-info">${contactInfo()}</div>${link('/help','前往帮助中心 '+icon('arrow'),'button primary')}`)}

function joinModal(){
  openModal('申请准入', `<p class="demo-note">原型演示，请使用测试信息。提交结果仅在本次预览中展示。</p>
    <form id="join-form"><label>机构全称<input name="name" required pattern=".*[^ ].*" maxlength="80" placeholder="请输入机构全称"></label>
    <label>联系人<input name="contact" required pattern=".*[^ ].*" maxlength="30" placeholder="请输入联系人姓名"></label>
    <label>手机号<input name="phone" type="tel" inputmode="numeric" pattern="1[3-9][0-9]{9}" maxlength="11" required title="请输入11位手机号" placeholder="请输入11位手机号"></label>
    <button class="button primary" type="submit">提交申请</button></form>`);
  $('#join-form').onsubmit = event => {
    event.preventDefault();
    const form=event.currentTarget;
    const name=form.elements.name.value.trim();
    const contact=form.elements.contact.value.trim();
    for(const field of [form.elements.name, form.elements.contact]){
      if(!field.value.trim()){field.value='';field.reportValidity();return}
    }
    form.parentElement.querySelector('.demo-note').remove();
    form.outerHTML=`<div role="status" tabindex="-1" class="join-receipt"><h3>已完成模拟提交</h3><p>${esc(name)} · 联系人 ${esc(contact)}</p><p>正式入驻申请需对接平台审核系统。</p><button class="button primary" id="join-done">完成</button></div>`;
    $('.join-receipt').focus();
    $('#join-done').onclick=closeModal;
  };
}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const list=[...$('.modal').querySelectorAll('button,a,input,select,textarea')];if(e.shiftKey&&(document.activeElement===list[0]||document.activeElement===$('.modal'))){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}});
window.addEventListener('hashchange',()=>{closeModal();render()});render();
